{"intent":"scan visible text in tuyển dụng HTML for user-unfit terms","expect":"file/line hits in visible text only; pass if suspicious text isolated","script":"python3 - <<'PY'
import os,re
from html import unescape
root='.'
paths=[]
for fn in os.listdir(root):
    if fn.endswith('.html') and any(k in fn for k in ['tuyen-dung','ung-vien','viec-lam','ung-tuyen','nha-tuyen-dung','dang-tin','ho-so','tai-khoan','don-ung-tuyen','quan-ly-tin','danh-sach-ung-vien']):
        paths.append(fn)
for d in ['tuyen-dung','ung-vien']:
    if os.path.isdir(d):
        for name in sorted(os.listdir(d)):
            if name.endswith('.html'):
                paths.append(os.path.join(d,name))
paths=sorted(dict.fromkeys(paths))
terms=[
    'dashboard','mô phỏng','auth','session','luồng','vai trò','truy cập nhanh',
    'liền mạch','đi tiếp','hệ thống sẽ','hệ thống ghi nhận','tạo sẵn nội dung',
    'lưu thông tin .json','.json','mở zalo','copy sẵn','public','chuẩn hóa','quy trình',
    'khu chức năng','khu dành','đúng khu','theo vai trò'
]
pat=re.compile('|'.join(re.escape(t) for t in terms), re.I)
script_re=re.compile(r'<script\b.*?</script>', re.I|re.S)
style_re=re.compile(r'<style\b.*?</style>', re.I|re.S)
tag_re=re.compile(r'<[^>]+>')
for path in paths:
    text=open(path,encoding='utf-8').read()
    cleaned=script_re.sub('', style_re.sub('', text))
    lines=cleaned.splitlines()
    hits=[]
    for i,line in enumerate(lines,1):
        raw=line.strip()
        if not raw:
            continue
        visible=unescape(tag_re.sub(' ', raw))
        visible=' '.join(visible.split())
        if visible and pat.search(visible):
            hits.append((i,visible))
    if hits:
        print('###',path)
        for i,vis in hits[:40]:
            print(f'{i}: {vis[:220]}')
        print()
