import os,re
from html import unescape
paths=[]
for fn in os.listdir('.'):
    if fn.endswith('.html') and any(k in fn for k in ['tuyen-dung','ung-vien','viec-lam','ung-tuyen','nha-tuyen-dung','dang-tin','ho-so','tai-khoan','don-ung-tuyen','quan-ly-tin','danh-sach-ung-vien']):
        paths.append(fn)
for d in ['tuyen-dung','ung-vien']:
    if os.path.isdir(d):
        for name in os.listdir(d):
            if name.endswith('.html'):
                paths.append(os.path.join(d,name))
paths=sorted(dict.fromkeys(paths))
terms=['hệ thống','quy trình','tính năng','mô phỏng','nội bộ','quản lý']
pat=re.compile('|'.join(re.escape(t) for t in terms), re.I)
script_re=re.compile(r'<script\b.*?</script>', re.I|re.S)
style_re=re.compile(r'<style\b.*?</style>', re.I|re.S)
tag_re=re.compile(r'<[^>]+>')
for path in paths:
    hits=[]
    text=open(path,encoding='utf-8').read()
    cleaned=script_re.sub('', style_re.sub('', text))
    for i,line in enumerate(cleaned.splitlines(),1):
        vis=' '.join(unescape(tag_re.sub(' ', line)).split())
        if vis and pat.search(vis):
            hits.append((i,vis))
    if hits:
        print('###',path)
        for i,vis in hits[:8]:
            print(f'{i}:{vis}')
        print()
